    {
      "id": "domain-purchase",
      "title": "Domain purchase skepticism",
      "claims": [
        {
          "text": "User P2 has not bought a domain.",
          "evidence": [2]
        },
        {
          "text": "P4 suggests nobody will buy a domain for this project.",
          "evidence": [9, 10]
        }
      ]
    },
    {
      "id": "app-profitability",
      "title": "Low profitability of the considered web/app product",
