        {
          "text": "Web platform is the simplest but far less profitable than Android/iOS.",
          "evidence": [11]
        },
        {
          "text": "SEO performance is poor; the site does not appear even on the 10th Google page.",
          "evidence": [11]
        },
        {
          "text": "No external traffic from social media and no contextual ads; app stores promote new apps better.",
          "evidence": [11]
        },
        {
          "text": "User retention is near zero due to immediate paywall after 10 seconds.",
          "evidence": [11]
        },
        {
          "text": "Conversion is presumed zero because the product does not simplify anything or integrate with banks or tax cabinets.",
          "evidence": [11]
        },
        {
          "text": "Successful similar projects use very fast delivery (< 1 week) and cross‑platform stacks like Flutter, copying popular ideas.",
          "evidence": [12]
        },
        {
          "text": "P1 doubts the product will sell, betting no one will buy it within a month.",
          "evidence": [17]
        }
      ]
    },
    {
      "id": "source-code-password",
      "title": "Source code access and password concerns",
      "claims": [
        {
          "text": "P4 claims the only password is stored locally as a 100 % discount promo code.",
          "evidence": [20]
        },
        {
          "text": "P1 asks if the source code or password can be found by searching.",
          "evidence": [21]
